(* [comment removed for export] *)
Lemma buf_bytes : forall m A w (bb : list byte) k,
  rw_cells usegs m A [C8 w; CB 4096 bb] -> 0 <= k <= 4096 ->
  bytes_at usegs m (A + 8) (firstn (Z.to_nat k) bb) /\ Z.of_nat (length (firstn (Z.to_nat k) bb)) = k.
Proof.
  intros m A w bb k RC K.
  pose proof (rw_cells_bytes_at _ _ _ _ RC) as B. cbn [cells_bytes cbytes] in B. rewrite app_nil_r in B.
  destruct RC as [[WF _] _]. cbn in WF. destruct WF as (_ & LB & _).
  destruct (proj1 (bytes_at_app _ _ _ _ _) B) as [_ B2]. rewrite length_le8 in B2. change (Z.of_nat 8) with 8 in B2.
  rewrite <- (firstn_skipn (Z.to_nat k) bb) in B2.
  destruct (proj1 (bytes_at_app _ _ _ _ _) B2) as [B3 _].
  split; [exact B3|]. rewrite length_firstn. lia.
Qed.

(* [comment removed for export] *)
Definition ipf_pf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (E lo p L : Z) (bs' : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m' p' E' g' (n1 n2 v1 v2 : word) bsz bb,
      ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
               F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp + -104); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -4288)
      /\ rw_cells usegs m' (bv_unsigned sp + -4248) [C8 (wz p')]
      /\ rw_cells usegs m' (bv_unsigned sp + -120) [C8 n1; C8 n2]
      /\ rw_cells usegs m' (bv_unsigned sp + -136) [C8 v1; C8 v2]
      /\ rw_cells usegs m' (bv_unsigned sp + -4240) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096
      /\ rw_cells usegs m' E (ErrCodeCells E')
      /\ bytes_at usegs m' p bs' /\ PfTab m'
      /\ pf_out EC_clear E' p L (bv_unsigned sp + -4232) p' n1 n2 v1 v2 bsz
      /\ HttpCat m' g' /\ XStatics m'.

Lemma ipf_pf_call : forall ra (sp : word) gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (E lo p L : Z) (bs' : list byte) (g : bool) (nm0 vl0 : list byte) (bsz0 : Z) (bb0 : list byte),
  rw_cells usegs m (bv_unsigned sp + -4248) [C8 (wz p)] ->
  rw_cells usegs m (bv_unsigned sp + -120) [CB 16 nm0] ->
  rw_cells usegs m (bv_unsigned sp + -136) [CB 16 vl0] ->
  rw_cells usegs m (bv_unsigned sp + -4240) [C8 (wz bsz0); CB 4096 bb0] -> 0 <= bsz0 <= 4096 ->
  rw_cells usegs m E (ErrCodeCells EC_clear) ->
  bytes_at usegs m p bs' -> L = p + Z.of_nat (length bs') -> PfTab m ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp + -4288) ->
  lo + 4528 <= bv_unsigned sp -> 0xb8000 <= lo -> ((0 < p /\ L <= 0x10000) \/ 0x95090 <= p) -> L <= lo -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  mem_inv usegs m ->
  evt usegs (ipf_pf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E lo p L bs' m)
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 s0 s1
              (Z_to_bv 64 (bv_unsigned sp + -4248)) (wz L) (Z_to_bv 64 (bv_unsigned sp + -120)) (Z_to_bv 64 (bv_unsigned sp + -136))
              (Z_to_bv 64 (bv_unsigned sp + -4240)) (wz E) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_FIELD) fc None m (seg_rom usegs)).
