    (q p bsz : Z) (j16 jt bb : list byte) (vl nm : list cell) (g : bool),
  ipf_ctx m m1 sp (ipf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo c pad7 pad2 p0 bs q EC_clear g ->
